--------------------------------------------------------------------------------
--- FORK MACHINES
--- Missing buildings for EV and IV:
---   * fill tier categories (e.g. the EV fluid solidifier can also do MV/HV/EV recipes)
---   * EV multiblocks whose item existed but could not be placed
---   * IV basic machines (copies of the EV machines, shifted one tier up)
---   * IV multiblocks (GT++ "industrial" machines) from 20-iv-age-entity.lua
--- Sprites in graphics/entity/fork/ are generated by tools/gen_sprites.py.
--------------------------------------------------------------------------------

local TIERS = { "lv", "mv", "hv", "ev", "iv", "luv", "zpm", "uv", "uhv", "uev", "uiv", "umv", "uxv", "max" }
local TIER_INDEX = {}
for i, t in ipairs(TIERS) do TIER_INDEX[t] = i end

local SPRITE_PATH = "__gregtorio-continued__/graphics/entity/fork/"

local function tier_of(name)
	local t = name:match("^(%a+)%-")
	return t and TIER_INDEX[t] and t or nil
end

local function category_exists(c)
	return data.raw["recipe-category"][c] ~= nil
end

--- Scale energy values like "1.28MW"
local function scale_energy(s, factor)
	local num, unit = s:match("^([%d%.]+)(%a+)$")
	local mult = { W = 1, kW = 1e3, MW = 1e6, GW = 1e9 }
	local watts = tonumber(num) * mult[unit] * factor
	if watts >= 1e9 then return string.format("%.4gGW", watts / 1e9) end
	if watts >= 1e6 then return string.format("%.4gMW", watts / 1e6) end
	return string.format("%.4gkW", watts / 1e3)
end

--- All existing categories "<tier>-<rest>" up to and including max_tier
local function tier_categories(rest, max_tier)
	local out = {}
	for i = 1, TIER_INDEX[max_tier] do
		local c = TIERS[i] .. "-" .. rest
		if category_exists(c) then table.insert(out, c) end
	end
	return out
end

local function add_unique(list, items)
	local seen = {}
	for _, v in pairs(list) do seen[v] = true end
	for _, v in pairs(items) do
		if not seen[v] then table.insert(list, v); seen[v] = true end
	end
	return list
end

--- Fill a machine's categories with all lower (and its own) tiers
local function tier_fill(categories, machine_tier)
	local result = {}
	for _, c in pairs(categories) do
		table.insert(result, c)
		local ct, rest = c:match("^(%a+)%-(.+)$")
		if ct and TIER_INDEX[ct] and TIER_INDEX[ct] <= TIER_INDEX[machine_tier] then
			add_unique(result, tier_categories(rest, machine_tier))
		end
	end
	return add_unique({}, result)
end

--- Graphics set from generated sprites (idle: 1 frame, working: vertical strip)
local function fork_graphics(sprite_name, width_px, height_px, frames)
	return {
		idle_animation = { layers = { {
			filename = SPRITE_PATH .. sprite_name .. "-idle.png",
			width = width_px, height = height_px,
			frame_count = 1, repeat_count = frames, shift = { 0, 0 },
		} } },
		animation = { layers = { {
			filename = SPRITE_PATH .. sprite_name .. "-working.png",
			width = width_px, height = height_px,
			frame_count = frames, line_length = 1, animation_speed = 0.3, shift = { 0, 0 },
		} } },
	}
end

--- New machine as a copy of an existing one
---   def = { name, source, categories, crafting_speed, energy_usage, sprite = {name, frames} | nil,
---           size = {w, h} (only without fluid boxes), keep_fluids = true|false, icon }
local function clone_machine(def)
	local src = data.raw["assembling-machine"][def.source]
	if not src then log("FORK-MACHINE: missing source: " .. def.source) return nil end
	local m = table.deepcopy(src)
	m.name = def.name
	m.minable = { mining_time = 0.5, result = def.name }
	m.crafting_categories = def.categories
	m.crafting_speed = def.crafting_speed or m.crafting_speed
	m.energy_usage = def.energy_usage or m.energy_usage
	m.fast_replaceable_group = def.fast_replaceable_group or m.fast_replaceable_group
	if def.icon then m.icon = def.icon; m.icon_size = 32 end
	if def.keep_fluids == false then
		m.fluid_boxes = nil
		m.fluid_boxes_off_when_no_fluid_recipe = nil
	end
	local w, h
	if def.size then
		w, h = def.size[1], def.size[2]
		m.collision_box = { { -w / 2 + 0.2, -h / 2 + 0.2 }, { w / 2 - 0.2, h / 2 - 0.2 } }
		m.selection_box = { { -w / 2, -h / 2 }, { w / 2, h / 2 } }
	else
		w = src.selection_box[2][1] - src.selection_box[1][1]
		h = src.selection_box[2][2] - src.selection_box[1][2]
	end
	if def.sprite then
		m.graphics_set = fork_graphics(def.sprite[1], w * 32, h * 32, def.sprite[2] or 1)
	end
	data:extend({ m })
	return m
end

--- Point an item at an entity (for items whose place_result was commented out)
local function set_place_result(item_name, entity_name)
	local item = data.raw.item[item_name]
	if not item then log("FORK-MACHINE: missing item: " .. item_name) return end
	item.place_result = entity_name
end



--------------------------------------------------------------------------------
--- 1) FILL TIER CATEGORIES (existing LV-EV machines)
---    e.g. the EV fluid solidifier only had LV recipes, the EV macerator no HV/EV
--------------------------------------------------------------------------------

for name, m in pairs(data.raw["assembling-machine"]) do
	local t = tier_of(name)
	if t and m.crafting_categories and TIER_INDEX[t] <= TIER_INDEX["ev"] then
		m.crafting_categories = tier_fill(m.crafting_categories, t)
	end
end



--- Chemical baths had two fluid INPUTS and no output. All bath recipes need at most
--- 1 fluid in + 1 fluid out (e.g. the platinum line) -> the second port becomes an output (south).
for name, m in pairs(data.raw["assembling-machine"]) do
	local is_bath = false
	for _, c in pairs(m.crafting_categories or {}) do
		if c:match("%-chemical%-bath%-recipes$") then is_bath = true end
	end
	if is_bath and m.fluid_boxes and #m.fluid_boxes == 2 then
		local out = m.fluid_boxes[2]
		out.production_type = "output"
		local h = m.selection_box[2][2]
		for _, pc in pairs(out.pipe_connections) do
			pc.flow_direction = "output"
			pc.direction = defines.direction.south
			pc.position = { pc.position[1], h - 0.5 }
		end
	end
end

--- Issue #635: GT's electrolyzer gives its gases and water as cells in six item slots (gregtech/api/recipe/RecipeMaps.java:
--- 820-821, maxIO(2, 6, 1, 1)); without cells the decompositions need a third fluid output (trona and vermiculite: hydrogen,
--- oxygen and water): the 3x3 electrolyzers get one between their two (south)
for _, m in pairs(data.raw["assembling-machine"]) do
	local electrolyzer = false
	for _, c in pairs(m.crafting_categories or {}) do
		if c:match("^%a+%-electrolyzer%-recipes$") then electrolyzer = true end
	end
	if electrolyzer and m.selection_box and m.selection_box[2][2] == 1.5 and m.fluid_boxes and #m.fluid_boxes == 4 then
		m.fluid_boxes[5] = fluid_port(0, 1, "output", defines.direction.south)
	end
end

--- Issue #356: GT's chemical bath and laser engraver maps take 2 fluids in and give 2 out (gregtech/api/recipe/
--- RecipeMaps.java: chemicalBathRecipes maxIO(2, 6, 2, 2), laserEngraverRecipes maxIO(4, 4, 2, 2); the netherite chain's
--- extraction and crystallization use them): the 3x3 baths get a second input (north) and output (south), the 3x3
--- laser engravers two outputs (south), on the free tiles of their sides.
local function add_port(m, src, kind, direction, x, y)
	local b = table.deepcopy(src)
	b.production_type = kind
	for _, pc in pairs(b.pipe_connections) do
		pc.flow_direction = kind
		pc.direction = direction
		pc.position = { x, y }
	end
	m.fluid_boxes[#m.fluid_boxes + 1] = b
end
for _, m in pairs(data.raw["assembling-machine"]) do
	local bath, engraver = false, false
	for _, c in pairs(m.crafting_categories or {}) do
		if c:match("%-chemical%-bath%-recipes$") then bath = true end
		if c:match("%-laser%-engraver%-recipes$") then engraver = true end
	end
	local h = m.selection_box and m.selection_box[2][2]
	if h == 1.5 and m.fluid_boxes and #m.fluid_boxes == 2 then
		if bath then
			add_port(m, m.fluid_boxes[1], "input", defines.direction.north, 1, -1)
			add_port(m, m.fluid_boxes[2], "output", defines.direction.south, -1, 1)
		elseif engraver then
			add_port(m, m.fluid_boxes[1], "output", defines.direction.south, -1, 1)
			add_port(m, m.fluid_boxes[1], "output", defines.direction.south, 1, 1)
		end
	end
end



