	--- UXV machines (134-fork-uxv.lua): universium cable, eternal coils
	uxv = {
		["spacetime-cable"]      = "universium-cable",
		["infinity-coil-block"]  = "spacetime-coil-block",
		["spacetime-coil-block"] = "eternal-coil-block",
	},
	--- MAX machines (141-fork-max.lua): magmatter cable; the eternal coil stays (GT has no coil above it)
	max = {
		["universium-cable"]     = "magmatter-cable",
		["spacetime-coil-block"] = "eternal-coil-block",
	},
}
local function item_exists(n)
	for t, _ in pairs(defines.prototypes.item) do
		if data.raw[t] and data.raw[t][n] then return true end
	end
	return false
end
local function shift_name(n, to_tier)
	local special = SPECIAL_SHIFT[to_tier] or {}
	if special[n] and item_exists(special[n]) then return special[n] end
	local t, rest = n:match("^(%a+)%-(.+)$")
	if t and TIER_INDEX[t] and TIERS[TIER_INDEX[t] + 1] then
		local shifted = TIERS[TIER_INDEX[t] + 1] .. "-" .. rest
		if item_exists(shifted) then return shifted end
	end
	return n
end
local function shift_list(list, to_tier)
	local out = {}
	for _, i in pairs(list or {}) do
		local c = table.deepcopy(i)
		if c.type ~= "fluid" then c.name = shift_name(c.name, to_tier) end
		table.insert(out, c)
	end
	return out
end

