--- Upgrade multiblocks keep the EV sprite of their source; the GT energy hatches of their tier are an extra
--- layer of the same size on it (<tier>-<base>-hatches.png from tools/gen_sprites.py, UPGRADE_MULTIBLOCKS).
--- The copy of the previous tier brings that tier's layer along, it is replaced.
local function set_tier_hatches(m, name)
	for _, key in pairs({ "idle_animation", "animation" }) do
		local anim = m.graphics_set and m.graphics_set[key]
		if anim then
			if not anim.layers then
				anim = { layers = { anim } }
				m.graphics_set[key] = anim
			end
			local layers = {}
			for _, l in pairs(anim.layers) do
				if not (l.filename or ""):match("%-hatches%.png$") then layers[#layers + 1] = l end
			end
			local b = layers[1]
			layers[#layers + 1] = {
				filename = SPRITE_PATH .. name .. "-hatches.png",
				width = b.width, height = b.height, scale = b.scale, shift = b.shift,
				frame_count = 1, repeat_count = (b.frame_count or 1) * (b.repeat_count or 1),
				animation_speed = b.animation_speed,
			}
			anim.layers = layers
		end
	end
end

--- Issue #148: a basic machine one tier up keeps the graphics set of its source (size, frame count, animation speed: in
--- the end the EV machine's, made by make_electric_machine from upstream's asset) with its own files, upstream's asset with
--- the casing in the tier's colour (tools/gen_sprites.py, basic_machine).
local function tier_graphics(src, name)
	local g = src.graphics_set and table.deepcopy(src.graphics_set)
	if not (g and g.idle_animation and g.animation) then return nil end
	for key, suffix in pairs({ idle_animation = "-idle.png", animation = "-working.png" }) do
		for _, layer in pairs(g[key].layers or { g[key] }) do layer.filename = SPRITE_PATH .. name .. suffix end
	end
	return g
end

--- Create a machine one tier up (entity, item, recipe). Global so 110-fork-luv.lua can use it.
--- sprite_frames: the machine gets the sprites of tools/gen_sprites.py; a basic machine (a graphics set with an idle and
--- a working animation) keeps its source's frame count, other machines get sprite_frames frames.
function fork_make_tier_machine(base, from_tier, to_tier, sprite_frames, unlock_tech)
	local src_name, new_name = from_tier .. "-" .. base, to_tier .. "-" .. base
	local hatches = not sprite_frames and UPGRADE_HATCHES[base]
	local src = data.raw["assembling-machine"][src_name]
	if not src then log("FORK-MACHINE: no source machine " .. src_name) return end
	local categories = table.deepcopy(src.crafting_categories)
	local extra = {}
	for _, c in pairs(categories) do
		local ct, rest = c:match("^(%a+)%-(.+)$")
		if ct and TIER_INDEX[ct] then add_unique(extra, tier_categories(rest, to_tier)) end
	end
	categories = add_unique(categories, extra)

	local icon = (sprite_frames or hatches) and ("__gregtorio-continued__/graphics/icons/fork/" .. new_name .. ".png") or nil
	local m = clone_machine{
		name = new_name, source = src_name, categories = categories,
		crafting_speed = src.crafting_speed * 2,
		energy_usage = scale_energy(src.energy_usage, 2),
		sprite = sprite_frames and { new_name, sprite_frames } or nil,
		icon = icon,
	}
	if m and hatches then set_tier_hatches(m, new_name) end
	if m and sprite_frames then m.graphics_set = tier_graphics(src, new_name) or m.graphics_set end

	--- Item
	local src_item = data.raw.item[src_name]
	local item = table.deepcopy(src_item)
	item.name = new_name
	item.place_result = new_name
	item.order = (src_item.order or "") .. "-" .. to_tier
	local sg = item.subgroup or ""
	if sg:match("age%-production%-machine$") then item.subgroup = to_tier .. "-age-production-machine" end
	if sg:match("age%-multiblocks$") then item.subgroup = "subgroup-" .. to_tier .. "-age-multiblocks" end
	if icon then item.icon = icon; item.icon_size = 32 end
	data:extend({ item })

	--- Recipe
	local src_recipe = data.raw.recipe[src_name]
	local r = table.deepcopy(src_recipe)
	r.name = new_name
	r.enabled = false
	r.ingredients = shift_list(src_recipe.ingredients, to_tier)
	r.results = shift_list(src_recipe.results, to_tier)
	for _, res in pairs(r.results) do if res.name == src_name then res.name = new_name end end
	if r.main_product then r.main_product = new_name end
	--- Upgrade multiblocks: the previous version goes in, not the new version itself
	for _, ing in pairs(r.ingredients) do if ing.name == new_name then ing.name = src_name end end
	data:extend({ r })
	if unlock_tech then fork_add_unlock(unlock_tech, new_name) end
end

for _, t in pairs({ "iv", "luv", "zpm" }) do
	if not data.raw["item-subgroup"][t .. "-age-production-machine"] then
		data:extend({ { type = "item-subgroup", name = t .. "-age-production-machine", group = "production", order = "i-z-" .. t } })
	end
end

for _, base in pairs(IV_BASIC_MACHINES) do fork_make_tier_machine(base, "ev", "iv", 6, "iv-machines") end
for _, base in pairs(IV_UPGRADE_MACHINES) do fork_make_tier_machine(base, "ev", "iv", nil, "iv-machines") end



